function effectControls(){const specs=(designs[current.id]||[]).map((spec,i)=>({spec,i})).filter(({spec})=>(!['background-color','--w'].includes(spec[2])||(current.id==='xray'&&spec[0]==='.xray-mask-layer'))&&!(current.id==='asciiDither'&&state.visible?.['.ascii-dither-modes']===false));const box=document.createElement('fieldset');box.className='group personal';box.innerHTML='<legend>Характер эффекта</legend>'+specs.map(({spec:[sel,label,prop,type,value,min,max],i})=>`<label class="field"><span>${label} <output>${state.design?.[i]??value}${type==='range'?' px':''}</output></span><input data-design="${i}" type="${type}" ${min!==undefined?`min="${min}" max="${max}" step="${type==='number'?'.05':'1'}"`:''} value="${state.design?.[i]??value}"></label>`).join('')+(current.id==='asciiDither'?`<label class="field"><span>Рисунок фона</span><select id="ascii-mode"><option value="ascii">Символы</option><option value="dither">Квадраты</option><option value="dot">Точки</option></select></label><label class="field"><span>Скорость движения волн</span><input id="wave-speed" type="range" min="0" max="3" step=".1" value="${state.waveSpeed??1}"></label>`:'');document.getElementById('extended').prepend(box);box.querySelectorAll('[data-design]').forEach(input=>input.oninput=()=>{state.design||={};state.design[input.dataset.design]=input.value;input.previousElementSibling.querySelector('output').value=input.value+(input.type==='range'?' px':'');sync()});if(current.id==='asciiDither'){document.getElementById('ascii-mode').value=state.asciiMode||'ascii';document.getElementById('ascii-mode').onchange=e=>{state.asciiMode=e.target.value;rebuildPreview()};document.getElementById('wave-speed').onchange=e=>{state.waveSpeed=+e.target.value;rebuildPreview()}}}

const sceneSelectors={glassFolder:'.gf-desk',invert:'#mk-effect',scramble:'#mk-effect',dirUnderline:'#mk-effect',tilt:'#mk-effect'};
function canvasBackground(code){let result=code.replaceAll("{ alpha: false }","{ alpha: true }");result=result.replace(/ctx\.fillStyle = ([^;\n]+);\s*ctx\.fillRect\(0, 0, width, height\);/g,(_,color)=>`if(window.MK_CONFIG?.transparent){ctx.clearRect(0,0,width,height)}else{ctx.fillStyle=window.MK_CONFIG?.backgroundOverride?window.MK_CONFIG.background:(${color});ctx.fillRect(0,0,width,height);}`);
result=result.replace(/const baseIconSize = ([\d.]+);/,(_,n)=>`let baseIconSize = Math.min(${n}, Math.max(20,(innerWidth-70-(dockApps.length-1)*8)/dockApps.length));window.addEventListener('resize',()=>{baseIconSize=Math.min(${n},Math.max(20,(innerWidth-70-(dockApps.length-1)*8)/dockApps.length));mouseX=null;dockInner.style.height=baseIconSize+'px';currentPositions=calcPositions(currentScales);kickDock();});`);
result=result.replaceAll("ctx.fillStyle = '#C5F03A';", "ctx.fillStyle = window.MK_CONFIG?.inkColor||'#C5F03A';").replaceAll("offCtx.fillStyle = '#C5F03A';", "offCtx.fillStyle = window.MK_CONFIG?.inkColor||'#C5F03A';").replaceAll("offCtx.fillStyle = '#FF3366';", "offCtx.fillStyle = window.MK_CONFIG?.accentColor||'#FF3366';");
result=result.replaceAll('rgba(${nodeColor},','rgba(${window.MK_CONFIG?.nodeRGB||(window.MK_CONFIG?.backgroundOverride&&parseInt(window.MK_CONFIG.background.slice(1),16)>0x888888?"35,35,40":nodeColor)},').replaceAll('rgba(${accentColor},','rgba(${window.MK_CONFIG?.accentRGB||accentColor},');
result=result.replace(/(?<!off)ctx\.fillStyle = ([^;\n]+);\s*ctx\.fillRect\(0, 0, w, h\);/g,(_,color)=>`if(window.MK_CONFIG?.transparent){ctx.clearRect(0,0,w,h)}else{ctx.fillStyle=window.MK_CONFIG?.backgroundOverride?window.MK_CONFIG.background:(${color});ctx.fillRect(0,0,w,h);}`);return result;}
const removable={
xray:[['.xray-text','Надпись снаружи круга'],['.xray-mask-text','Надпись внутри круга']],ribbon:[],cursorLine:[],reveal:[['.rev-floater','Всплывающая фотография']],magnetic:[],scramble:[],gooey:[['.gooey-blob','Капли вокруг кнопки']],invert:[['.inv-card p','Небольшая подпись']],accordion:[],trail:[],tilt:[['.tilt-glare','Блик'],['.tilt-card span','Надпись']],pixel:[['.pixel-grid','Скрывающие квадраты']],spotlight:[['.spotlight-content','Надпись']],noise:[['.noise-text','Надпись'],['.noise-bg','Зерно']],pillnav:[['.pill-logo','Логотип'],['.pill-links','Ссылки меню']],dirUnderline:[],difference:[['.diff-text','Надпись'],['.diff-bg-img','Фоновая фотография']],customCursor:[['.cc-btn','Кнопка для демонстрации'],['.cc-dot','Точка курсора'],['.cc-follower','Кольцо вокруг курсора']],discCarousel:[['.dcc-sheen','Блики на дисках']],vignetteBloom:[['.ascii-vignette','Затемнение по краям']],constellation:[['.constellation-content','Надпись в центре']],morphGallery:[['.morph-btn','Стрелки переключения']],expandableTabs:[['.ext-separator','Разделитель']],glassFolder:[['.gf-label','Название и число файлов'],['.gf-key','Кнопка добавления']],macosDock:[['.mac-dock-tooltip','Названия приложений'],['.mac-dock-dot','Точка активного приложения']],hoverButton:[['.ihb-dot-bg','Точка рядом с надписью']],asciiDither:[['.ascii-dither-modes','Панель выбора рисунка']]};
function controls(images){
 document.getElementById('controls').innerHTML=`<fieldset class="group"><legend>1. Фон эффекта</legend><label class="field"><span>Цвет фона</span><input id="background" type="color" value="${state.background}"></label><label class="check"><input id="transparent" type="checkbox" ${state.transparent?'checked':''}> Убрать фон</label><p class="muted">Меняет заливку самого эффекта. Шахматная сетка в превью означает прозрачность.</p><label class="field"><span>Высота блока <output id="height-val">${state.height} px</output></span><input id="height" type="range" min="500" max="800" step="10" value="${state.height}"></label>${current.id==='xray'?`<label class="field"><span>Размер круга <output id="radius-val">${state.radius||120} px</output></span><input id="radius" type="range" min="30" max="250" value="${state.radius||120}"></label>`:''}</fieldset>${fields.length?`<fieldset class="group"><legend>2. Надписи</legend><label class="field"><span>Выберите надпись</span><select id="text-select">${fields.map((f,i)=>`<option value="${i}">${esc(current.id==='xray'?(i===0?'Снаружи круга':'Внутри круга'):f.text.slice(0,40))}</option>`).join('')}</select></label><label class="field"><span>Текст</span><textarea id="text-value"></textarea></label><label class="field"><span>Размер <output id="font-val"></output></span><input id="font" type="range" min="10" max="160"></label><label class="field"><span>Цвет надписи</span><input id="text-color" type="color" value="#ffffff"></label></fieldset>`:''}${images.length?`<details class="editor-section"><summary>Фотографии (${images.length})</summary>${images.map((im,i)=>`<label class="field"><span>Фото ${i+1}</span><input data-image="${esc(im.selector)}" value="${esc(state.images[im.selector]||im.url)}" placeholder="Прямая ссылка на изображение"></label>`).join('')}</details>`:''}`;
 document.getElementById('background').oninput=e=>{state.background=e.target.value;state.backgroundOverride=true;state.transparent=false;document.getElementById('transparent').checked=false;sync()};document.getElementById('transparent').onchange=e=>{state.transparent=e.target.checked;sync()};document.getElementById('height').oninput=e=>{state.height=+e.target.value;document.getElementById('height-val').value=state.height+' px';sync()};document.getElementById('radius')?.addEventListener('input',e=>{state.radius=+e.target.value;document.getElementById('radius-val').value=state.radius+' px';sync()});
 if(fields.length){selected=0;document.getElementById('text-select').onchange=e=>{selected=+e.target.value;showText()};document.getElementById('text-value').oninput=editText;document.getElementById('font').oninput=editText;document.getElementById('text-color').oninput=e=>{state.elements||={};state.elements[fields[selected].selector]||={};state.elements[fields[selected].selector].color=e.target.value;sync()};showText()}
 document.querySelectorAll('[data-image]').forEach(el=>el.onchange=()=>{if(!/^(https?:|data:image\/)/i.test(el.value)){notify('Вставьте прямую ссылку https:// на фото');return}state.images[el.dataset.image]=el.value;sync()});
}
function extendedControls(elements){
 const host=document.createElement('div');host.id='extended';document.getElementById('controls').append(host);host.innerHTML='<div id="parts-controls"></div><div id="motion-controls"></div>'+(current.id==='macosDock'?'<fieldset class="group"><legend>Иконки Dock</legend><div id="dock-list"></div><button class="secondary" id="dock-add">+ Добавить иконку</button><button class="primary" id="dock-apply">Применить Dock</button></fieldset>':'');
 effectControls();canvasColors();
 const choices=removable[current.id]||[];const parts=document.getElementById('parts-controls');if(choices.length){parts.innerHTML='<fieldset class="group"><legend>Что показывать</legend><p class="muted">Отключите детали, которые вам не нужны. Выбранный рисунок и само движение сохранятся.</p>'+choices.map(([sel,label],i)=>`<label class="check"><input data-visible="${i}" type="checkbox" ${state.visible?.[sel]===false?'':'checked'}> ${label}</label>`).join('')+'</fieldset>';parts.querySelectorAll('[data-visible]').forEach(el=>el.onchange=()=>{state.visible||={};state.visible[choices[+el.dataset.visible][0]]=el.checked;sync();rebuildPreview()})}
 const paramInfo={cellSize:['Размер сетки',4,40,1],cursorRadius:['Радиус реакции на курсор',20,350,5],maxHistory:['Длина следа',3,50,1],SPRING_K:['Сила возврата точек',1,40,1],DAMPING:['Плавность движения',.1,.99,.01],MAX_CONN_DIST:['Длина соединений',20,150,5],scaleK:['Размер папки',.4,1,.05],baseIconSize:['Размер иконок',24,80,1],maxScale:['Увеличение иконок',1,2,.1],effectWidth:['Область увеличения',50,350,10],baseSpacing:['Расстояние между иконками',0,20,1]};
 const code=[...(state.source||current.source).matchAll(/<script>([\s\S]*?)<\/script>/g)].map(m=>m[1]).join('');const found=[...new Map([...code.matchAll(/const (\w+) = (-?\d+(?:\.\d+)?);/g)].filter(m=>paramInfo[m[1]]).map(m=>[m[1],m])).values()];
 const motion=document.getElementById('motion-controls');if(found.length){motion.innerHTML='<fieldset class="group"><legend>Движение и реакция</legend>'+found.map(m=>{const [label,min,max,step]=paramInfo[m[1]];return `<label class="field"><span>${label} <output>${state.params?.[m[1]]??m[2]}</output></span><input data-param="${m[1]}" type="range" min="${min}" max="${max}" step="${step}" value="${state.params?.[m[1]]??m[2]}"></label>`}).join('')+'</fieldset>';motion.querySelectorAll('[data-param]').forEach(el=>{el.oninput=()=>el.previousElementSibling.querySelector('output').value=el.value;el.onchange=()=>{state.params||={};state.params[el.dataset.param]=+el.value;rebuildPreview()}})}
 if(current.id==='macosDock')setupDock();
}

function canvasColors(){if(!['asciiDither','constellation','vignetteBloom'].includes(current.id))return;const box=document.createElement('fieldset');box.className='group';const constellation=current.id==='constellation';const fields=constellation?[['nodeColor','Цвет точек и соединений','#ffffff'],['accentColor','Цвет точек возле курсора','#c5f03a']]:[['inkColor','Цвет рисунка','#c5f03a'],...(current.id==='vignetteBloom'?[['accentColor','Второй цвет рисунка','#ff3366']]:[])];box.innerHTML='<legend>Цвета рисунка</legend>'+fields.map(([key,label,value])=>`<label class="field"><span>${label}</span><input data-ink="${key}" type="color" value="${state[key]||value}"></label>`).join('');document.getElementById('extended').prepend(box);box.querySelectorAll('[data-ink]').forEach(el=>el.oninput=()=>{state[el.dataset.ink]=el.value;const rgb=v=>[1,3,5].map(i=>parseInt(v.slice(i,i+2),16)).join(',');if(el.dataset.ink==='nodeColor')state.nodeRGB=rgb(el.value);if(el.dataset.ink==='accentColor')state.accentRGB=rgb(el.value);sync()})}
